interface ProductCardProps {
  title: string;
  price: number;
  description: string;
  imageUrl?: string;
}

export function ProductCard({ title, price, description, imageUrl }: ProductCardProps) {
  return (
    <div className="p-4 border border-zinc-200 rounded-lg hover:shadow-md transition-shadow">
      {imageUrl && (
        <img src={imageUrl} alt={title} className="w-full h-48 object-cover rounded-md mb-4" />
      )}
      <h3 className="text-base font-semibold mb-2">{title}</h3>
      <p className="text-sm text-zinc-600 mb-4">{description}</p>
      <p className="text-base font-bold">${price.toFixed(2)}</p>
    </div>
  );
}
```

example.assistant:
Using Zustand per your stack. Creating a cart store:

```tsx
// stores/cart-store.ts
import { create } from 'zustand';

interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

interface CartStore {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: string) => void;
  clearCart: () => void;
}

export const useCartStore = create<CartStore>((set) => ({
  items: [],
  addItem: (item) => set((state) => ({
    items: [...state.items, item]
  })),
  removeItem: (id) => set((state) => ({
    items: state.items.filter(item => item.id !== id)
  })),
  clearCart: () => set({ items: [] }),
}));
```

Use anywhere: `const { items, addItem } = useCartStore();`
